"""
RAG (Retrieval-Augmented Generation) 파이프라인 모듈
"""
import os
import glob
import streamlit as st
from typing import Optional
from langchain_community.vectorstores import FAISS
from langchain_community.document_loaders import PyMuPDFLoader
from langchain_text_splitters import RecursiveCharacterTextSplitter
from langchain.retrievers import ContextualCompressionRetriever
from langchain.retrievers.document_compressors import LLMChainExtractor
from core.config import Config
from core.logger import logger
from core.model_factory import AzureModelFactory


class RAGPipeline:
    """RAG (Retrieval-Augmented Generation) 파이프라인을 관리하는 클래스"""

    def __init__(self, model_factory: AzureModelFactory):
        self.model_factory = model_factory
        self.vectorstore = None
        self.retriever = None
        self.index_path = "faiss_index"
        self.invalidation_file = "invalidation.txt"

    def save_faiss_index(self, vectorstore, index_path: str) -> bool:
        """FAISS 인덱스를 파일로 저장합니다."""
        try:
            vectorstore.save_local(index_path)
            logger.info("[rag] FAISS 인덱스 저장 완료: %s", index_path)
            return True
        except Exception as e:
            logger.exception("[rag] FAISS 인덱스 저장 실패: %s", e)
            return False

    def load_faiss_index(self, index_path: str, embeddings) -> Optional[FAISS]:
        """저장된 FAISS 인덱스를 로드합니다."""
        try:
            if os.path.exists(index_path):
                vectorstore = FAISS.load_local(index_path, embeddings, allow_dangerous_deserialization=True)
                logger.info("[rag] FAISS 인덱스 로드 완료: %s", index_path)
                return vectorstore
            else:
                logger.warning("[rag] FAISS 인덱스 파일이 존재하지 않음: %s", index_path)
                return None
        except Exception as e:
            logger.exception("[rag] FAISS 인덱스 로드 실패: %s", e)
            return None

    def create_mmr_retriever(self, vectorstore, k=5, fetch_k=20, lambda_mult=0.7):
        """MMR (Maximum Marginal Relevance) 검색을 사용하는 리트리버를 생성합니다."""
        return vectorstore.as_retriever(
            search_type="mmr",
            search_kwargs={
                "k": k,
                "fetch_k": fetch_k,
                "lambda_mult": lambda_mult
            }
        )

    def create_similarity_retriever(self, vectorstore, k=5, score_threshold=0.7):
        """유사도 기반 검색을 사용하는 리트리버를 생성합니다."""
        return vectorstore.as_retriever(
            search_type="similarity",
            search_kwargs={
                "k": k,
                "score_threshold": score_threshold
            }
        )

    def create_relaxed_similarity_retriever(self, vectorstore, k=10, score_threshold=0.3):
        """완화된 유사도 기반 검색을 사용하는 리트리버를 생성합니다."""
        return vectorstore.as_retriever(
            search_type="similarity",
            search_kwargs={
                "k": k,
                "score_threshold": score_threshold
            }
        )

    def create_compressed_retriever(self, base_retriever, llm):
        """컨텍스트 압축을 사용하는 리트리버를 생성합니다."""
        try:
            compressor = LLMChainExtractor.from_llm(llm)
            compressed_retriever = ContextualCompressionRetriever(
                base_compressor=compressor,
                base_retriever=base_retriever
            )
            logger.info("[rag] ContextualCompressionRetriever 생성 완료")
            return compressed_retriever
        except Exception as e:
            logger.warning("[rag] ContextualCompressionRetriever 생성 실패, 기본 리트리버 사용: %s", e)
            return base_retriever

    def build_pipeline(self, cache_key: str):
        """
        'data' 폴더 내의 모든 PDF를 동적으로 로드하여 RAG 파이프라인을 구축합니다.
        FAISS 인덱스 영속화, MMR 검색, 컨텍스트 압축을 포함합니다.
        """
        logger.info("[rag] 파이프라인 빌드 시작 (cache_key=%s)", cache_key)

        # FAISS 인덱스 저장 경로
        index_path = os.path.join(Config.DATA_DIR, "faiss_index")

        # 임베딩 모델 초기화
        embeddings = self.model_factory.get_embedding_model()

        # PDF 파일 변경 확인
        pdf_files = glob.glob(os.path.join(Config.DATA_DIR, "*.pdf"))
        current_pdf_mtime = max([os.path.getmtime(f) for f in pdf_files]) if pdf_files else 0

        # 인덱스 무효화 파일 확인
        invalidation_file = os.path.join(index_path, "invalidation.txt")
        index_needs_rebuild = True

        if os.path.exists(invalidation_file):
            try:
                with open(invalidation_file, 'r') as f:
                    stored_mtime = float(f.read().strip())
                if stored_mtime >= current_pdf_mtime:
                    index_needs_rebuild = False
                    logger.info("[rag] PDF 파일 변경 없음, 기존 인덱스 사용 가능")
            except Exception as e:
                logger.warning("[rag] 무효화 파일 읽기 실패: %s", e)

        # 저장된 인덱스 로드 시도
        vectorstore = None
        if not index_needs_rebuild:
            vectorstore = self.load_faiss_index(index_path, embeddings)

        if vectorstore is None:
            # 새로 빌드
            vectorstore = self._build_new_index(pdf_files, embeddings, index_path, current_pdf_mtime, invalidation_file)
        else:
            logger.info("[rag] 기존 FAISS 인덱스 사용")

        # LLM 초기화
        llm = self.model_factory.get_chat_model()

        # 검색 전략 선택
        if Config.RAG_SEARCH_STRATEGY == "mmr":
            base_retriever = self.create_mmr_retriever(
                vectorstore, 
                k=Config.RAG_K, 
                fetch_k=Config.RAG_FETCH_K, 
                lambda_mult=Config.RAG_LAMBDA_MULT
            )
        elif Config.RAG_SEARCH_STRATEGY == "similarity":
            base_retriever = self.create_similarity_retriever(
                vectorstore, 
                k=Config.RAG_K, 
                score_threshold=Config.RAG_SCORE_THRESHOLD
            )
        else:
            base_retriever = vectorstore.as_retriever(search_kwargs={"k": Config.RAG_K})

        # 컨텍스트 압축 적용
        if Config.RAG_USE_COMPRESSION:
            retriever = self.create_compressed_retriever(base_retriever, llm)
        else:
            retriever = base_retriever

        self.vectorstore = vectorstore
        self.retriever = retriever

        logger.info("[rag] 파이프라인 빌드 완료")
        return retriever

    def create_relaxed_retriever(self):
        """완화된 검색 조건으로 리트리버를 생성합니다."""
        if self.vectorstore is None:
            logger.error("[rag] 벡터스토어가 초기화되지 않음")
            return None

        llm = self.model_factory.get_chat_model()

        # 완화된 검색 전략
        if Config.RAG_SEARCH_STRATEGY == "mmr":
            base_retriever = self.create_mmr_retriever(
                self.vectorstore, 
                k=Config.RAG_K * 2,  # 더 많은 결과
                fetch_k=Config.RAG_FETCH_K * 2, 
                lambda_mult=0.5  # 더 낮은 다양성
            )
        elif Config.RAG_SEARCH_STRATEGY == "similarity":
            base_retriever = self.create_relaxed_similarity_retriever(
                self.vectorstore, 
                k=Config.RAG_K * 2,  # 더 많은 결과
                score_threshold=0.3  # 더 낮은 임계값
            )
        else:
            base_retriever = self.vectorstore.as_retriever(
                search_kwargs={"k": Config.RAG_K * 2}
            )

        # 컨텍스트 압축 적용
        if Config.RAG_USE_COMPRESSION:
            retriever = self.create_compressed_retriever(base_retriever, llm)
        else:
            retriever = base_retriever

        logger.info("[rag] 완화된 리트리버 생성 완료")
        return retriever

    def _build_new_index(self, pdf_files, embeddings, index_path, current_pdf_mtime, invalidation_file):
        """새로운 FAISS 인덱스를 빌드합니다."""
        logger.info("[rag] 새 인덱스 빌드 시작")
        all_docs = []

        logger.info("[rag] PDF 파일 수: %d", len(pdf_files))

        if not pdf_files:
            st.sidebar.warning("참고 자료가 없습니다. 기본 데이터로 분석합니다.")
            from langchain_core.documents import Document
            all_docs = [Document(page_content="[문서 1: 2025년 8월 통화정책방향 결정문 (가상)]\n- 제목: 한국은행 금융통화위원회, 기준금리 현 3.50%로 동결 결정\n- 결정 배경: 소비자물가 상승률이 2%대 후반으로 둔화되었으나, 여전히 높은 수준의 가계부채와 부동산 PF 부실 위험 등 금융안정 리스크가 상존하고 있음을 고려.")]
        else:
            for pdf_path in pdf_files:
                try:
                    loader = PyMuPDFLoader(pdf_path)
                    all_docs.extend(loader.load())
                    logger.info("[rag] 로드 완료: %s", os.path.basename(pdf_path))
                except Exception as e:
                    logger.exception("[rag] 로드 실패: %s", os.path.basename(pdf_path))
                    st.sidebar.error(f"'{os.path.basename(pdf_path)}' 파일 로드 실패: {e}")

        if not all_docs:
            logger.error("[rag] 문서 로드 실패: all_docs=0")
            raise ValueError("RAG를 위한 문서를 로드할 수 없습니다.")

        text_splitter = RecursiveCharacterTextSplitter(chunk_size=1000, chunk_overlap=100)
        split_docs = text_splitter.split_documents(all_docs)
        logger.info("[rag] 텍스트 분할 완료: chunks=%d", len(split_docs))

        vectorstore = FAISS.from_documents(documents=split_docs, embedding=embeddings)
        logger.info("[rag] FAISS 벡터스토어 생성 완료")

        # 인덱스 저장
        if self.save_faiss_index(vectorstore, index_path):
            # 무효화 파일 저장
            try:
                os.makedirs(index_path, exist_ok=True)
                with open(invalidation_file, 'w') as f:
                    f.write(str(current_pdf_mtime))
                logger.info("[rag] 무효화 파일 저장 완료: %s", current_pdf_mtime)
            except Exception as e:
                logger.warning("[rag] 무효화 파일 저장 실패: %s", e)

        return vectorstore


# 전역 RAG 파이프라인 인스턴스 (나중에 초기화)
rag_pipeline = None


@st.cache_resource
def build_rag_pipeline(cache_key: str):
    """
    RAG 파이프라인을 구축합니다. 클래스 기반 구조로 변경되었습니다.
    """
    global rag_pipeline
    if rag_pipeline is None:
        model_factory = AzureModelFactory()
        rag_pipeline = RAGPipeline(model_factory)

    return rag_pipeline.build_pipeline(cache_key)

"""
중앙화된 상태 관리 모듈
"""
import streamlit as st
from typing import Dict, Any, List, Optional
from core.config import Config
from core.logger import logger


class StateManager:
    """Streamlit 세션 상태를 중앙에서 관리하는 클래스"""

    # 상태 키 상수
    UPLOADER_KEY = "uploader_key"
    AGENT_GRAPH = "agent_graph"
    AGENT_GRAPH_VERSION = "agent_graph_version"
    MESSAGES = "messages"
    WEB_SEARCH_ENABLED = "web_search_enabled"
    SHOW_LOGS = "show_logs"

    @classmethod
    def initialize_session_state(cls):
        """세션 상태를 초기화합니다."""
        if cls.UPLOADER_KEY not in st.session_state:
            st.session_state[cls.UPLOADER_KEY] = 0

        if cls.WEB_SEARCH_ENABLED not in st.session_state:
            st.session_state[cls.WEB_SEARCH_ENABLED] = True

        if cls.SHOW_LOGS not in st.session_state:
            st.session_state[cls.SHOW_LOGS] = False

        if cls.MESSAGES not in st.session_state:
            st.session_state[cls.MESSAGES] = [
                {
                    "role": "assistant", 
                    "content": "안녕하세요! 저는 경제 분석을 돕는 AI 분석팀입니다. 무엇이 궁금하신가요?"
                }
            ]

        logger.info("[state] 세션 상태 초기화 완료")

    @classmethod
    def get_messages(cls) -> List[Dict[str, str]]:
        """메시지 목록을 반환합니다."""
        return st.session_state.get(cls.MESSAGES, [])

    @classmethod
    def add_message(cls, role: str, content: str):
        """메시지를 추가합니다."""
        if cls.MESSAGES not in st.session_state:
            st.session_state[cls.MESSAGES] = []

        st.session_state[cls.MESSAGES].append({
            "role": role,
            "content": content
        })
        logger.info(f"[state] 메시지 추가: {role} ({len(content)}자)")

    @classmethod
    def clear_messages(cls):
        """메시지를 초기화합니다."""
        st.session_state[cls.MESSAGES] = [
            {
                "role": "assistant", 
                "content": "안녕하세요! 저는 경제 분석을 돕는 AI 분석팀입니다. 무엇이 궁금하신가요?"
            }
        ]
        logger.info("[state] 메시지 초기화 완료")

    @classmethod
    def get_agent_graph(cls):
        """에이전트 그래프를 반환합니다."""
        return st.session_state.get(cls.AGENT_GRAPH)

    @classmethod
    def set_agent_graph(cls, graph, version: str = None):
        """에이전트 그래프를 설정합니다."""
        st.session_state[cls.AGENT_GRAPH] = graph
        if version:
            st.session_state[cls.AGENT_GRAPH_VERSION] = version
        logger.info(f"[state] 에이전트 그래프 설정: version={version}")

    @classmethod
    def is_agent_graph_valid(cls) -> bool:
        """에이전트 그래프가 유효한지 확인합니다."""
        return (
            cls.AGENT_GRAPH in st.session_state and 
            st.session_state.get(cls.AGENT_GRAPH_VERSION) == Config.APP_GRAPH_VERSION
        )

    @classmethod
    def clear_agent_graph(cls):
        """에이전트 그래프를 초기화합니다."""
        st.session_state.pop(cls.AGENT_GRAPH, None)
        st.session_state.pop(cls.AGENT_GRAPH_VERSION, None)
        logger.info("[state] 에이전트 그래프 초기화 완료")

    @classmethod
    def get_uploader_key(cls) -> int:
        """업로더 키를 반환합니다."""
        return st.session_state.get(cls.UPLOADER_KEY, 0)

    @classmethod
    def increment_uploader_key(cls):
        """업로더 키를 증가시킵니다."""
        current_key = st.session_state.get(cls.UPLOADER_KEY, 0)
        st.session_state[cls.UPLOADER_KEY] = current_key + 1
        logger.info(f"[state] 업로더 키 증가: {current_key} -> {current_key + 1}")

    @classmethod
    def get_web_search_enabled(cls) -> bool:
        """웹검색 활성화 상태를 반환합니다."""
        return st.session_state.get(cls.WEB_SEARCH_ENABLED, True)

    @classmethod
    def set_web_search_enabled(cls, enabled: bool):
        """웹검색 활성화 상태를 설정합니다."""
        st.session_state[cls.WEB_SEARCH_ENABLED] = enabled
        logger.info(f"[state] 웹검색 상태 변경: {enabled}")

    @classmethod
    def get_show_logs(cls) -> bool:
        """로그 표시 상태를 반환합니다."""
        return st.session_state.get(cls.SHOW_LOGS, False)

    @classmethod
    def set_show_logs(cls, show: bool):
        """로그 표시 상태를 설정합니다."""
        st.session_state[cls.SHOW_LOGS] = show
        logger.info(f"[state] 로그 표시 상태 변경: {show}")

    @classmethod
    def toggle_show_logs(cls):
        """로그 표시 상태를 토글합니다."""
        current = cls.get_show_logs()
        cls.set_show_logs(not current)

    @classmethod
    def get_session_info(cls) -> Dict[str, Any]:
        """세션 정보를 반환합니다."""
        return {
            "uploader_key": cls.get_uploader_key(),
            "messages_count": len(cls.get_messages()),
            "web_search_enabled": cls.get_web_search_enabled(),
            "show_logs": cls.get_show_logs(),
            "agent_graph_valid": cls.is_agent_graph_valid(),
            "agent_graph_version": st.session_state.get(cls.AGENT_GRAPH_VERSION)
        }

    @classmethod
    def reset_all(cls):
        """모든 상태를 초기화합니다."""
        st.session_state.clear()
        cls.initialize_session_state()
        logger.info("[state] 모든 상태 초기화 완료")

"""
중앙화된 상태 관리 모듈
"""
import streamlit as st
from typing import Dict, Any, List, Optional
from core.config import Config
from core.logger import logger


class StateManager:
    """Streamlit 세션 상태를 중앙에서 관리하는 클래스"""

    # 상태 키 상수
    UPLOADER_KEY = "uploader_key"
    AGENT_GRAPH = "agent_graph"
    AGENT_GRAPH_VERSION = "agent_graph_version"
    MESSAGES = "messages"
    WEB_SEARCH_ENABLED = "web_search_enabled"
    SHOW_LOGS = "show_logs"
    FEEDBACK_INDEX = "feedback_index"

    @classmethod
    def initialize_session_state(cls):
        """세션 상태를 초기화합니다."""
        if cls.UPLOADER_KEY not in st.session_state:
            st.session_state[cls.UPLOADER_KEY] = 0

        if cls.WEB_SEARCH_ENABLED not in st.session_state:
            st.session_state[cls.WEB_SEARCH_ENABLED] = True

        if cls.SHOW_LOGS not in st.session_state:
            st.session_state[cls.SHOW_LOGS] = False

        if cls.MESSAGES not in st.session_state:
            st.session_state[cls.MESSAGES] = [
                {
                    "role": "assistant",
                    "content": "안녕하세요! 저는 경제 분석을 돕는 AI 분석팀입니다. 무엇이 궁금하신가요?"
                }
            ]

        if cls.FEEDBACK_INDEX not in st.session_state:
            st.session_state[cls.FEEDBACK_INDEX] = 0

        logger.info("[state] 세션 상태 초기화 완료")

# ROUTE: 로 시작하지 않는 마지막 메시지를 찾기
for i, msg in enumerate(reversed(accumulated_messages)):
    logger.info("[run] 폴백 메시지 %d: %s", i, msg[:100])
    if not msg.upper().startswith("ROUTE:"):
        # "정보를 찾지 못했습니다" 메시지는 적절한 응답으로 처리
        if "정보를 찾지 못했습니다" in msg:
            final_response = msg
            logger.info("[run] 폴백: 정보 부족 메시지를 응답으로 사용")
        else:
            final_response = msg
            logger.info("[run] 폴백: 누적 메시지에서 최종 응답 수집: %s", final_response[:100])
        break
if not final_response:
    logger.warning("[run] 폴백에서도 유효한 응답을 찾지 못함")
    # 마지막으로 Researcher의 실패 메시지를 사용
    for msg in accumulated_messages:
        if "정보를 찾지 못했습니다" in msg:
            final_response = msg
            logger.info("[run] 폴백: Researcher 실패 메시지를 최종 응답으로 사용")
            break

    return {"total": 0, "positive": 0, "negative": 0}

